import React from 'react';
import { View, StyleSheet, Text } from 'react-native';

export default function BrandLogo() {
  return (
    <View style={styles.wrapper}>
      <View style={styles.iconCircle}>
        <View style={styles.marker}>
          <View style={styles.markerTip} />
        </View>
        <View style={styles.centerDot} />
      </View>
      <View>
        <Text style={styles.text}>GearSpot</Text>
        <Text style={styles.tagline}>Vuokraa lähelläsi.</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  wrapper: { flexDirection: 'row', alignItems: 'center' },
  iconCircle: {
    width: 48,
    height: 48,
    borderRadius: 24,
    backgroundColor: '#15948b',
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 12,
    shadowColor: '#15948b',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.2,
    shadowRadius: 6,
    elevation: 4
  },
  marker: {
    width: 22,
    height: 28,
    borderRadius: 11,
    backgroundColor: '#fff',
    justifyContent: 'flex-end',
    alignItems: 'center',
    paddingBottom: 3
  },
  markerTip: {
    width: 0,
    height: 0,
    borderLeftWidth: 6,
    borderRightWidth: 6,
    borderTopWidth: 10,
    borderLeftColor: 'transparent',
    borderRightColor: 'transparent',
    borderTopColor: '#fff'
  },
  centerDot: {
    position: 'absolute',
    width: 12,
    height: 12,
    borderRadius: 6,
    backgroundColor: '#15948b'
  },
  text: {
    fontSize: 22,
    fontWeight: '800',
    color: '#0f2f3d'
  },
  tagline: {
    fontSize: 12,
    color: '#58717d',
    marginTop: 2
  }
});
